#!/usr/bin/env python3
"""Emulates `docker run` + `docker stop` for /app/entrypoint.sh without a Docker daemon.

The entrypoint is run as the "container init": SIGTERM is delivered to it only if
it has a SIGTERM handler installed (the kernel rule for a PID-namespace init
signalled from the parent namespace, which is what `docker stop` does). If it
has not exited STOP_TIMEOUT seconds after SIGTERM, everything is SIGKILLed
(docker's default 10 s). When the init exits, all remaining processes are
SIGKILLed (PID-namespace teardown).

The real /app/app.py is temporarily replaced by an instrumented copy whose
SIGTERM handler additionally writes a random nonce, so the shutdown marker can
only be attributed to the Python application's own handler.
"""
import ctypes, os, secrets, shutil, signal, subprocess, sys, time

HERE = os.path.dirname(os.path.abspath(__file__))
APP = "/app/app.py"
ENTRY = "/app/entrypoint.sh"
DATA = "/app/data"
STOP_TIMEOUT = 10.0     # docker stop default
MAX_EXIT = 5.0          # "within a few seconds, not hitting the default 10-second timeout"

fails = []
def fail(msg):
    fails.append(msg); print("FAIL:", msg, flush=True)

def sigterm_caught(pid):
    try:
        with open(f"/proc/{pid}/status") as f:
            for line in f:
                if line.startswith("SigCgt:"):
                    return bool(int(line.split()[1], 16) & (1 << (signal.SIGTERM - 1)))
    except OSError:
        pass
    return False

def children_of_me():
    me = str(os.getpid()); out = []
    for p in os.listdir("/proc"):
        if not p.isdigit(): continue
        try:
            with open(f"/proc/{p}/stat") as f:
                st = f.read()
            ppid = st[st.rindex(")") + 2:].split()[1]
            if ppid == me: out.append(int(p))
        except (OSError, ValueError):
            pass
    return out

def descendants(root):
    tree = {}
    for p in os.listdir("/proc"):
        if not p.isdigit(): continue
        try:
            with open(f"/proc/{p}/stat") as f:
                st = f.read()
            ppid = int(st[st.rindex(")") + 2:].split()[1])
            tree.setdefault(ppid, []).append(int(p))
        except (OSError, ValueError):
            pass
    out, stack = [], [root]
    while stack:
        for c in tree.get(stack.pop(), []):
            out.append(c); stack.append(c)
    return out

def kill_all():
    # we are a subreaper, so every orphan is our child
    for _ in range(20):
        pids = set(children_of_me())
        for c in list(pids): pids.update(descendants(c))
        if not pids: break
        for p in pids:
            try: os.kill(p, signal.SIGKILL)
            except OSError: pass
        time.sleep(0.1)
        try:
            while os.waitpid(-1, os.WNOHANG)[0] > 0: pass
        except ChildProcessError:
            pass

def main():
    if not os.path.isfile(ENTRY):
        fail(f"{ENTRY} missing"); return
    nonce = secrets.token_hex(16)
    nonce_file = os.path.join(DATA, ".verifier_" + secrets.token_hex(6))
    src = open(os.path.join(HERE, "app_original.py")).read()
    anchor = '    print("Cleanup complete, exiting gracefully", flush=True)\n'
    assert anchor in src
    inst = src.replace(anchor,
        f'    open({nonce_file!r}, "w").write("{nonce}:" + signal_name + "\\n")\n' + anchor)

    backup = APP + ".verifier_bak"
    if os.path.exists(APP): shutil.copy2(APP, backup)
    with open(APP, "w") as f: f.write(inst)
    os.chmod(APP, 0o755)
    shutil.rmtree(DATA, ignore_errors=True); os.makedirs(DATA, exist_ok=True)
    os.chmod(ENTRY, os.stat(ENTRY).st_mode | 0o111)

    libc = ctypes.CDLL(None, use_errno=True)
    libc.prctl(36, 1, 0, 0, 0)  # PR_SET_CHILD_SUBREAPER

    log = open("/tmp/entrypoint_log.txt", "wb")
    try:
        proc = subprocess.Popen([ENTRY], cwd="/app", stdin=subprocess.DEVNULL,
                                stdout=log, stderr=subprocess.STDOUT, start_new_session=True)
    except OSError as e:
        fail(f"cannot execute entrypoint: {e}"); _restore(backup); return
    try:
        # wait for the app to be up and writing data
        out = os.path.join(DATA, "output.txt")
        t0 = time.time()
        while time.time() - t0 < 20:
            if proc.poll() is not None: break
            if os.path.exists(out) and open(out).read().count("data_entry_") >= 3: break
            time.sleep(0.2)
        time.sleep(0.5)
        if proc.poll() is not None:
            fail(f"entrypoint exited by itself before stop (rc={proc.returncode})")
        elif not (os.path.exists(out) and "data_entry_" in open(out).read()):
            fail("application never started writing data entries")

        # docker stop
        delivered = False
        exited_in = None
        if proc.poll() is None:
            if sigterm_caught(proc.pid):
                os.kill(proc.pid, signal.SIGTERM); delivered = True
            else:
                print("init has no SIGTERM handler: SIGTERM ignored (PID-1 semantics)", flush=True)
            t1 = time.time()
            while time.time() - t1 < STOP_TIMEOUT:
                if proc.poll() is not None:
                    exited_in = time.time() - t1; break
                time.sleep(0.05)
        kill_all()  # SIGKILL after timeout / namespace teardown
        try: proc.wait(timeout=5)
        except subprocess.TimeoutExpired: pass
        print(f"sigterm delivered={delivered} exited_in={exited_in}", flush=True)
        if exited_in is None:
            fail("container did not exit after SIGTERM before the 10 s timeout (would be SIGKILLed)")
        elif exited_in > MAX_EXIT:
            fail(f"container took {exited_in:.1f}s to exit (> {MAX_EXIT}s)")

        marker = os.path.join(DATA, "shutdown_complete")
        if not os.path.isfile(marker):
            fail("/app/data/shutdown_complete not created")
        elif open(marker).read().strip() != "shutdown_complete:SIGTERM":
            fail(f"unexpected marker content {open(marker).read()!r}")
        if not os.path.isfile(nonce_file) or open(nonce_file).read().strip() != f"{nonce}:SIGTERM":
            fail("the Python app's own SIGTERM handler did not run to completion")
        if os.path.exists(out):
            lines = open(out).read().splitlines()
            if not lines or lines[-1] != "--- END OF DATA (clean shutdown) ---":
                fail("output.txt does not end with the clean-shutdown line")
        log.close()
        print("---- entrypoint output ----"); print(open("/tmp/entrypoint_log.txt", errors="replace").read()[-3000:])
    finally:
        kill_all()
        _restore(backup)

def _restore(backup):
    if os.path.exists(backup): shutil.move(backup, APP)

if __name__ == "__main__":
    main()
    print("RESULT:", "PASS" if not fails else "FAIL")
    sys.exit(0 if not fails else 1)
EOF
